macro_rules! deps {
    () => {
        Ok!();
    };
}

macro_rules! read_file {
    () => {
        deps!();
        # [doc = " Reads the contents of a file with a file header as defined in this module."] # [doc = ""] # [doc = " - Returns `Ok(Some(data, pos))` if the file existed and was generated by a"] # [doc = "   compatible compiler version. `data` is the entire contents of the file"] # [doc = "   and `pos` points to the first byte after the header."] # [doc = " - Returns `Ok(None)` if the file did not exist or was generated by an"] # [doc = "   incompatible version of the compiler."] # [doc = " - Returns `Err(..)` if some kind of IO error occurred while reading the"] # [doc = "   file."] pub (crate) fn read_file (path : & Path , report_incremental_info : bool , is_nightly_build : bool , cfg_version : & 'static str ,) -> io :: Result < Option < (Mmap , usize) > > { let file = match fs :: File :: open (path) { Ok (file) => file , Err (err) if err . kind () == io :: ErrorKind :: NotFound => return Ok (None) , Err (err) => return Err (err) , } ; let mmap = unsafe { Mmap :: map (file) } ? ; let mut file = io :: Cursor :: new (& * mmap) ; { debug_assert ! (FILE_MAGIC . len () == 4) ; let mut file_magic = [0u8 ; 4] ; file . read_exact (& mut file_magic) ? ; if file_magic != FILE_MAGIC { report_format_mismatch (report_incremental_info , path , "Wrong FILE_MAGIC") ; return Ok (None) ; } } { debug_assert ! (size_of_val (& HEADER_FORMAT_VERSION) == 2) ; let mut header_format_version = [0u8 ; 2] ; file . read_exact (& mut header_format_version) ? ; let header_format_version = (header_format_version [0] as u16) | ((header_format_version [1] as u16) << 8) ; if header_format_version != HEADER_FORMAT_VERSION { report_format_mismatch (report_incremental_info , path , "Wrong HEADER_FORMAT_VERSION") ; return Ok (None) ; } } { let mut rustc_version_str_len = [0u8 ; 1] ; file . read_exact (& mut rustc_version_str_len) ? ; let rustc_version_str_len = rustc_version_str_len [0] as usize ; let mut buffer = vec ! [0 ; rustc_version_str_len] ; file . read_exact (& mut buffer) ? ; if buffer != rustc_version (is_nightly_build , cfg_version) . as_bytes () { report_format_mismatch (report_incremental_info , path , "Different compiler version") ; return Ok (None) ; } } let post_header_start_pos = file . position () as usize ; Ok (Some ((mmap , post_header_start_pos))) }
    };
}

read_file!();